import{Module,VisualJoint}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,frame,mesh,plastic,metal}from'./geometry.js';import{stand,brick}from'./geometry-data.js';import{spec}from'./dimensions.js';
function assemblyFrame(host,name){const g=frame(host.body,name);g.rotation.x=Math.PI/2;return g;}
function native(host,g,data){const parts=addCadParts(host,data,{stand:plastic(0x292c29)});for(const p of Object.values(parts))g.add(p);return parts;}
export class BackBrick extends Module{static meta={id:'m5stack.unit.poe-cam-w-v11.back-brick',name:'PoE CAM-W v1.1 native Back-Brick',sku:'U121-B-V11 accessory',connector:spec.mount.connector};build(){const g=assemblyFrame(this,'PoE CAM-W v1.1 own native Back-Brick installation frame');this.body.updateWorldMatrix(true,true);const parts=native(this,g,brick);this.poeCamAccessory={frame:g,parts,brick:parts[brick[0].name]};}}
export class Stand extends Module{static meta={id:'m5stack.unit.poe-cam-w-v11.stand',name:'PoE CAM-W v1.1 native Stand',sku:'U121-B-V11 accessory',connector:spec.mount.connector};build(){const g=assemblyFrame(this,'PoE CAM-W v1.1 own native Stand installation frame');this.body.updateWorldMatrix(true,true);const parts=native(this,g,stand),clamp=parts[stand[0].name],leg=parts[stand[1].name],pivot=[0,.000105,-12.200757],axis=[.9999967377,-.0025543413,.00000083046];const bolt=new THREE.Mesh(new THREE.CylinderGeometry(2.45,2.45,14,48),metal());bolt.name='PoE CAM-W v1.1 real retained transverse Stand clamp bolt';bolt.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(...axis));bolt.position.fromArray(pivot);g.add(bolt);const head=new THREE.Mesh(new THREE.CylinderGeometry(3.6,3.6,1.8,6),metal());head.name='PoE CAM-W v1.1 retained external clamp hex nut';head.quaternion.copy(bolt.quaternion);head.position.fromArray(pivot).addScaledVector(new THREE.Vector3(...axis),7);g.add(head);const tilt=this.add(new VisualJoint({id:'tilt',label:'Stand clamp ↔ leg relative angle',axis,position:pivot,limitsDeg:[-20,40],meta:{visualRangeDeg:[-20,40],scope:'External relative native leg/foot vs fixed clamp rotation only;no motor,ground lock or host world-pose solver.',rangeSource:'Conservative appearance-derived range;not a rated hard stop.',axisSource:'Own native Stand actual Ø5.2 bore wall axis fit,including native≈0.146degree assembly yaw;fixed/leg source relative pose retained.'}}));g.add(tilt.object3d);tilt.object3d.position.fromArray(pivot);tilt.adopt(leg);this.poeCamAccessory={frame:g,parts,clamp,leg,bolt,head,tilt};}}
